CREATE TABLE public.location (
    pk bigint NOT NULL,
    created_time timestamp(6) without time zone NOT NULL,
    digest character varying(255),
    multi_ref integer,
    object_type smallint NOT NULL,
    object_size bigint NOT NULL,
    status smallint NOT NULL,
    storage_id character varying(255) NOT NULL,
    storage_path character varying(255) NOT NULL,
    tsuid character varying(255),
    uidmap_fk bigint,
    instance_fk bigint,
    CONSTRAINT location_object_type_check CHECK (((object_type >= 0) AND (object_type <= 1))),
    CONSTRAINT location_status_check CHECK (((status >= 0) AND (status <= 17)))
